+				continue;
+			}
+			children.push({
+				kind: "value",
+				value: fields[childKey],
+				key: childKey,
+				keyed: true,
+				isTopLevelToolResultDetails: isTopLevelMessageChild(value, key, childKey),
+				atomic: atomicNode,
+			});
+		}
+		pending.push({ kind: "end" });
